// Ran says "Ran {activities}"
// in the language the app shows under cx.
//
// A settled group's title, such as "Ran 2 commands · 1 file read".
func Ran(cx *core.Scope, activities string) string { return For(cx).Ran(activities) }

// Ran is the package's Ran in the language of msgs.
func (msgs Messages) Ran(activities string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.Ran(activities))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].Ran; f != nil {
			return f(activities)
		}
		switch lang {
		case "", "en":
			return "Ran " + msgs.arg(activities)
		case "zh-Hans":
			return "已执行：" + activities
		}
	}
}

