// CountRun says "{count, plural, one {{count} command} other {{count} commands}}"
// in the language the app shows under cx.
func CountRun(cx *core.Scope, count int) string { return For(cx).CountRun(count) }

// CountRun is the package's CountRun in the language of msgs.
func (msgs Messages) CountRun(count int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.CountRun(count))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].CountRun; f != nil {
			return f(count)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" command")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" commands")
			}
			return b.String()
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + " 个命令"
		}
	}
}

